test('TC_01 - Access Customer / Fleet Search', async ({ page }) => {
  await page.goto(BASE_URL + '/login');
  await page.getByLabel('Username').fill(MDUI_USER);
  await page.getByLabel('Password').fill(MDUI_PASSWORD);
  await page.getByRole('button', { name: 'Log In' }).click();
  await page.getByRole('link', { name: 'Accounts / Fleets' }).click();
  await page.getByRole('link', { name: 'Customer / Fleet Search' }).click();
  await expect(page.getByRole('heading', { name: 'Customer / Fleet Search' })).toBeVisible();
});

